WITH recent_accounts AS (SELECT * FROM accounts WHERE opened_date > '2023-07-30'), accounts_stats AS (SELECT CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END opened_cohort, COUNT(CASE WHEN status = 'FROZEN' THEN 1 END) frozen_count, SUM(balance) total_balance FROM recent_accounts GROUP BY CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT * FROM accounts_stats ORDER BY total_balance, opened_cohort LIMIT 5;
